def kthInMountain(nums, k):
    n = len(nums)
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < nums[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    peak = lo

    def count(x):
        a, b = 0, peak + 1
        while a < b:
            m = (a + b) // 2
            if nums[m] <= x:
                a = m + 1
            else:
                b = m
        left = a
        a, b = peak + 1, n
        while a < b:
            m = (a + b) // 2
            if nums[m] <= x:
                b = m
            else:
                a = m + 1
        return left + (n - a)

    lo, hi = min(nums[0], nums[-1]), nums[peak]
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
